draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw buckwheat
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.fillStyle = '#663300';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // draw wheat
  ctx.fillStyle = '#ffff00';
  ctx.beginPath();
  ctx.arc(W/2 + 100 * Math.sin(t), H/2, 30, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // draw stick figure
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2 + 50, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 70);
  ctx.lineTo(W/2 - 100, H/2 + 120);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 100);
  ctx.lineTo(W/2 - 80, H/2 + 130);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 100);
  ctx.lineTo(W/2 - 120, H/2 + 130);
  ctx.stroke();

  // draw speech bubble
  ctx.fillStyle = 'white';
  ctx.beginPath();
  ctx.arc(W/2 - 150, H/2 + 50, 40, 0, 2 * Math.PI);
  ctx.fill();
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.stroke();
  ctx.font = '20px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Not wheat!', W/2 - 150, H/2 + 50);

  ctx.restore();
}
